import ApplicationServices
import Testing
@testable import AXorcist

@Suite("AX action execution")
@MainActor
struct ActionExecutionTests {
    private struct UnexpectedActionError: Error {}

    @Test
    func `canonical action owner invokes the system boundary once`() throws {
        let element = Element(AXUIElementCreateSystemWide())
        var invocationCount = 0
        var receivedAction: String?

        let returnedElement = try element.performAction("AXPress") { _, action in
            invocationCount += 1
            receivedAction = action as String
            return .success
        }

        #expect(invocationCount == 1)
        #expect(receivedAction == "AXPress")
        #expect(CFEqual(returnedElement.underlyingElement, element.underlyingElement))
    }

    @Test
    func `canonical action owner preserves native AX errors`() {
        let element = Element(AXUIElementCreateSystemWide())

        #expect(throws: AccessibilitySystemError.self) {
            try element.performAction("AXPress") { _, _ in .cannotComplete }
        }

        do {
            try element.performAction("AXPress") { _, _ in .cannotComplete }
            Issue.record("Expected AccessibilitySystemError")
        } catch let error as AccessibilitySystemError {
            #expect(error.axError == .cannotComplete)
        } catch {
            Issue.record("Unexpected error type: \(error)")
        }
    }

    @Test
    func `utility preserves native AX errors and only generalizes unknown failures`() {
        #expect(
            AXUtilities.axError(forActionError: AccessibilitySystemError(.cannotComplete)) == .cannotComplete)
        #expect(AXUtilities.axError(forActionError: UnexpectedActionError()) == .failure)
    }

    @Test
    func `successful command action skips supported action discovery`() {
        let element = Element(AXUIElementCreateSystemWide())
        var invocationCount = 0
        var discoveryCount = 0

        let response = AXorcist().executeAction(
            action: "AXPress",
            on: element,
            value: nil,
            performer: { _, _ in invocationCount += 1 },
            supportedActions: { _ in
                discoveryCount += 1
                return ["AXPress"]
            })

        #expect(response.status == "success")
        #expect(invocationCount == 1)
        #expect(discoveryCount == 0)
    }

    @Test
    func `unsupported command action discovers diagnostics once after failure`() {
        let element = Element(AXUIElementCreateSystemWide())
        var discoveryCount = 0

        let response = AXorcist().executeAction(
            action: "AXPress",
            on: element,
            value: nil,
            performer: { _, _ in throw AccessibilitySystemError(.actionUnsupported) },
            supportedActions: { _ in
                discoveryCount += 1
                return ["AXRaise"]
            })

        #expect(response.error?.code == .actionNotSupported)
        #expect(response.error?.message.contains("Action is not supported") == true)
        #expect(response.error?.message.contains("Available actions: [AXRaise]") == true)
        #expect(discoveryCount == 1)
    }

    @Test
    func `cannot complete is preserved without retry or discovery`() {
        let element = Element(AXUIElementCreateSystemWide())
        var invocationCount = 0
        var discoveryCount = 0

        let response = AXorcist().executeAction(
            action: "AXPress",
            on: element,
            value: nil,
            performer: { _, _ in
                invocationCount += 1
                throw AccessibilitySystemError(.cannotComplete)
            },
            supportedActions: { _ in
                discoveryCount += 1
                return nil
            })

        #expect(response.error?.code == .actionFailed)
        #expect(response.error?.message.contains("Cannot complete operation") == true)
        #expect(response.error?.message.contains("-25204") == true)
        #expect(invocationCount == 1)
        #expect(discoveryCount == 0)
    }

    @Test(arguments: [
        (AXError.apiDisabled, AXErrorCode.permissionDenied),
        (.invalidUIElement, .elementNotFound),
        (.actionUnsupported, .actionNotSupported),
        (.illegalArgument, .invalidParameter),
        (.cannotComplete, .actionFailed),
    ])
    func `native action failures map to precise response codes`(_ error: AXError, _ code: AXErrorCode) {
        #expect(error.actionResponseCode == code)
    }
}

import AppKit
import Foundation
import Testing
@testable import AXorcist

@Suite(
    "AXorcist Action Integration Tests",
    .tags(.automation),
    .enabled(if: AXTestEnvironment.runAutomationScenarios))
@MainActor
struct ActionIntegrationTests {
    @Test(.tags(.automation))
    func `Discover AXPress on a native window button`() async throws {
        let (_, appElement) = try await setupTextEditAndGetInfo()
        defer { Task { await closeTextEdit() } }

        guard let appElement,
              let button = Element(appElement).mainWindow()?.closeButton()
        else {
            throw TestError.generic("Could not find TextEdit's close button.")
        }

        #expect(button.supportedActions()?.contains(AXActionNames.kAXPressAction) == true)
        #expect(button.isActionSupported(AXActionNames.kAXPressAction))
    }

    @Test(.tags(.automation))
    func `Perform AXSetValue on TextEdit`() async throws {
        let actionCommandId = "performaction-setvalue-\(UUID().uuidString)"
        let queryCommandId = "query-verify-setvalue-\(UUID().uuidString)"
        let textEditBundleId = "com.apple.TextEdit"
        let textAreaRole = ApplicationServices.kAXTextAreaRole as String
        let textToSet = "Hello from AXORC performAction test! Time: \(Date())"

        _ = try await setupTextEditAndGetInfo()
        defer { Task { await closeTextEdit() } }

        let textAreaLocator = Locator(criteria: [Criterion(attribute: "AXRole", value: textAreaRole)])

        try await performSetValueAction(
            actionCommandId: actionCommandId,
            textEditBundleId: textEditBundleId,
            textAreaLocator: textAreaLocator,
            textToSet: textToSet)

        try await verifyTextValue(
            queryCommandId: queryCommandId,
            textEditBundleId: textEditBundleId,
            textAreaLocator: textAreaLocator,
            expectedText: textToSet)
    }

    @Test(.tags(.automation))
    func `Extract text after setting value`() async throws {
        let setValueCommandId = "setvalue-for-extract-\(UUID().uuidString)"
        let extractTextCommandId = "extracttext-textedit-textarea-\(UUID().uuidString)"
        let textEditBundleId = "com.apple.TextEdit"
        let textAreaRole = ApplicationServices.kAXTextAreaRole as String
        let textToSetAndExtract = "Text to be extracted by AXORC. Unique: \(UUID().uuidString)"

        _ = try await setupTextEditAndGetInfo()
        defer { Task { await closeTextEdit() } }

        let textAreaLocator = Locator(criteria: [Criterion(attribute: "AXRole", value: textAreaRole)])

        try await performSetValueAction(
            actionCommandId: setValueCommandId,
            textEditBundleId: textEditBundleId,
            textAreaLocator: textAreaLocator,
            textToSet: textToSetAndExtract)

        try await extractAndVerifyText(
            extractTextCommandId: extractTextCommandId,
            textEditBundleId: textEditBundleId,
            textAreaLocator: textAreaLocator,
            expectedText: textToSetAndExtract)
    }

    // MARK: - Helper Functions

    private func performSetValueAction(
        actionCommandId: String,
        textEditBundleId: String,
        textAreaLocator: Locator,
        textToSet: String) async throws
    {
        let performActionEnvelope = CommandEnvelope(
            commandId: actionCommandId,
            command: .performAction,
            application: textEditBundleId,
            debugLogging: true,
            locator: textAreaLocator,
            actionName: "AXSetValue",
            actionValue: .string(textToSet))

        let response = try await executeCommand(performActionEnvelope)

        #expect(response.commandId == actionCommandId)
        #expect(
            response.success,
            "performAction command was not successful. Error: \(response.error?.message ?? "N/A")")

        try await Task.sleep(for: .milliseconds(100))
    }

    private func verifyTextValue(
        queryCommandId: String,
        textEditBundleId: String,
        textAreaLocator: Locator,
        expectedText: String) async throws
    {
        let queryEnvelope = CommandEnvelope(
            commandId: queryCommandId,
            command: .query,
            application: textEditBundleId,
            attributes: ["AXValue"],
            debugLogging: true,
            locator: textAreaLocator)

        let response = try await executeCommand(queryEnvelope)

        #expect(response.commandId == queryCommandId)
        #expect(
            response.success,
            "Query (verify) command failed. Error: \(response.error?.message ?? "N/A")")

        guard let attributes = response.data?.attributes else {
            throw TestError.generic("Attributes nil in query (verify) response.")
        }

        let retrievedValue = attributes["AXValue"]?.anyValue as? String
        #expect(
            retrievedValue == expectedText,
            "AXValue did not match. Expected: '\(expectedText)'. Got: '\(retrievedValue ?? "nil")'")

        #expect(response.debugLogs != nil)
    }

    private func extractAndVerifyText(
        extractTextCommandId: String,
        textEditBundleId: String,
        textAreaLocator: Locator,
        expectedText: String) async throws
    {
        let extractTextEnvelope = CommandEnvelope(
            commandId: extractTextCommandId,
            command: .extractText,
            application: textEditBundleId,
            debugLogging: true,
            locator: textAreaLocator)

        let response = try await executeCommand(extractTextEnvelope)

        #expect(response.commandId == extractTextCommandId)
        #expect(
            response.success,
            "extractText command failed. Error: \(response.error?.message ?? "N/A")")
        #expect(response.command == CommandType.extractText.rawValue)

        guard let attributes = response.data?.attributes else {
            throw TestError.generic("Attributes nil in extractText response.")
        }

        let extractedValue = attributes["AXValue"]?.anyValue as? String
        #expect(
            extractedValue == expectedText,
            "Extracted text did not match. Expected: '\(expectedText)'. Got: '\(extractedValue ?? "nil")'")

        #expect(response.debugLogs != nil)
        #expect(
            response.debugLogs?.contains { log in
                log.contains("Handling extractText command") || log.contains("handleExtractText completed")
            } == true,
            "Debug logs should indicate extractText execution.")
    }

    private func executeCommand(_ command: CommandEnvelope) async throws -> QueryResponse {
        let encoder = JSONEncoder()
        encoder.outputFormatting = .withoutEscapingSlashes
        let jsonData = try encoder.encode(command)
        guard let jsonString = String(data: jsonData, encoding: String.Encoding.utf8) else {
            throw TestError.generic("Failed to create JSON for command.")
        }

        print("Sending command: \(jsonString)")
        let result = try runAXORCCommand(arguments: [jsonString])
        let (output, errorOutput, exitCode) = (result.output, result.errorOutput, result.exitCode)

        #expect(exitCode == 0, "Command failed. Error: \(errorOutput ?? "N/A")")
        #expect(
            errorOutput?.isEmpty ?? true,
            "STDERR should be empty. Got: \(errorOutput ?? "")")

        guard let outputString = output, !outputString.isEmpty else {
            throw TestError.generic("Output string was nil or empty for command: \(command.commandId)")
        }
        guard let responseData = outputString.data(using: String.Encoding.utf8) else {
            throw TestError.generic("Failed to convert output string to data for command: \(command.commandId)")
        }

        return try JSONDecoder().decode(QueryResponse.self, from: responseData)
    }
}

import Foundation
import Testing
@testable import AXorcist

@Suite("Permission change stream")
nonisolated struct PermissionChangeStreamTests {
    /// Hang guard only. The blocked main queue or install hook stays held for the
    /// whole wait, so a join still fails; a short bound flakes on loaded CI.
    private static let cancellationTimeout: DispatchTimeInterval = .seconds(10)

    @Test
    func `permissionChanges cancel does not join the main queue`() async {
        let stream = await MainActor.run {
            AXPermissionHelpers.permissionChanges(interval: 60)
        }
        let completed = await Self.runOnDedicatedThread {
            Self.cancelCompletesWhileMainQueueIsBusy(stream: stream)
        }

        #expect(completed)
    }

    @Test
    func `permissionChanges skip start after an already-terminated stream`() async {
        let scheduled = PermissionTimerScheduleBox()
        let skipped = await Self.runOnDedicatedThread {
            Self.cancelBeforeQueuedStartRuns(scheduled: scheduled)
        }

        #expect(skipped)
        #expect(!scheduled.wasMarked)
    }

    @Test
    func `permissionChanges skip timer when cancellation wins installation race`() async {
        let scheduled = PermissionTimerScheduleBox()
        let skipped = await Self.runOnDedicatedThread {
            Self.cancelBeforeTimerInstallation(scheduled: scheduled)
        }

        #expect(skipped)
        #expect(!scheduled.wasMarked)
    }

    private nonisolated static func cancelCompletesWhileMainQueueIsBusy(
        stream: AsyncStream<Bool>) -> Bool
    {
        let consumeFinished = DispatchSemaphore(value: 0)
        let consume = Task.detached {
            for await _ in stream {}
            consumeFinished.signal()
        }

        let mainHeld = DispatchSemaphore(value: 0)
        let releaseMain = DispatchSemaphore(value: 0)
        DispatchQueue.main.async {
            mainHeld.signal()
            releaseMain.wait()
        }
        mainHeld.wait()

        Thread.detachNewThread {
            consume.cancel()
        }
        let finished = consumeFinished.wait(timeout: .now() + Self.cancellationTimeout) == .success
        releaseMain.signal()
        return finished
    }

    private nonisolated static func cancelBeforeQueuedStartRuns(
        scheduled: PermissionTimerScheduleBox) -> Bool
    {
        let mainHeld = DispatchSemaphore(value: 0)
        let streamCreated = DispatchSemaphore(value: 0)
        let releaseMain = DispatchSemaphore(value: 0)

        DispatchQueue.main.async {
            mainHeld.signal()
            streamCreated.wait()
            releaseMain.wait()
        }
        mainHeld.wait()

        _ = AXPermissionHelpers.permissionChanges(interval: 60) {
            scheduled.mark()
        }
        streamCreated.signal()
        releaseMain.signal()
        let flushed = DispatchSemaphore(value: 0)
        DispatchQueue.main.async {
            flushed.signal()
        }
        flushed.wait()
        return !scheduled.wasMarked
    }

    private nonisolated static func cancelBeforeTimerInstallation(
        scheduled: PermissionTimerScheduleBox) -> Bool
    {
        let installReached = DispatchSemaphore(value: 0)
        let releaseInstall = DispatchSemaphore(value: 0)
        let consumeFinished = DispatchSemaphore(value: 0)

        let stream = AXPermissionHelpers.permissionChanges(
            interval: 60,
            beforeTimerInstall: {
                installReached.signal()
                releaseInstall.wait()
            },
            onTimerScheduled: {
                scheduled.mark()
            })
        let consume = Task.detached {
            for await _ in stream {}
            consumeFinished.signal()
        }

        installReached.wait()
        consume.cancel()
        let cancelled = consumeFinished.wait(timeout: .now() + Self.cancellationTimeout) == .success
        releaseInstall.signal()

        let flushed = DispatchSemaphore(value: 0)
        DispatchQueue.main.async {
            flushed.signal()
        }
        flushed.wait()
        return cancelled && !scheduled.wasMarked
    }

    private nonisolated static func runOnDedicatedThread<Value: Sendable>(
        _ operation: @escaping @Sendable () -> Value) async -> Value
    {
        await withCheckedContinuation { continuation in
            Thread.detachNewThread {
                continuation.resume(returning: operation())
            }
        }
    }
}

private final nonisolated class PermissionTimerScheduleBox: @unchecked Sendable {
    private let lock = NSLock()
    private var marked = false

    func mark() {
        self.lock.lock()
        self.marked = true
        self.lock.unlock()
    }

    var wasMarked: Bool {
        self.lock.lock()
        defer { self.lock.unlock() }
        return self.marked
    }
}

import Testing
@testable import AXorcist

@MainActor
struct AccessibilityPermissionsTests {
    @Test
    func `Permission status reports Accessibility without legacy automation probes`() {
        let status = getPermissionsStatus()

        #expect(status.canUseAccessibility == (
            status.isAccessibilityApiEnabled && status.isProcessTrustedForAccessibility))
        #expect(status.overallErrorMessages.isEmpty)
    }

    @available(*, deprecated, message: "Exercises the retained legacy compatibility surface.")
    @Test
    func `Legacy automation targets remain source compatible but unknown`() {
        let status = getPermissionsStatus(checkAutomationFor: ["com.example.Test"])

        #expect(status.automationStatus.isEmpty)
        #expect(status.canAutomate(bundleID: "com.example.Test") == nil)
        #expect(status.overallErrorMessages.isEmpty)
    }
}

import AppKit
import Testing
@testable import AXorcist

@Suite(
    "AXorcist Element Search Tests",
    .tags(.automation),
    .enabled(if: AXTestEnvironment.runAutomationScenarios))
@MainActor
struct ElementSearchTests {
    @Test(.tags(.automation))
    func `Search through a menu bar container`() async throws {
        _ = try await setupTextEditAndGetInfo()
        defer { Task { await closeTextEdit() } }

        let command = CommandEnvelope(
            commandId: "query-menu-bar-item",
            command: .query,
            application: "com.apple.TextEdit",
            locator: Locator(criteria: [
                Criterion(attribute: "AXRole", value: AXRoleNames.kAXMenuBarItemRole),
            ]))

        let response = try await self.runQuery(command: command, encoder: JSONEncoder())
        #expect(response.success)
        #expect(response.data?.attributes?["AXRole"]?.stringValue == AXRoleNames.kAXMenuBarItemRole)
    }

    @Test(.tags(.automation))
    func `Search a window by its generic AXTitle criterion`() async throws {
        let (_, appElement) = try await setupTextEditAndGetInfo()
        defer { Task { await closeTextEdit() } }

        guard let appElement,
              let title = Element(appElement).mainWindow()?.title()
        else {
            throw TestError.generic("Could not read TextEdit's main window title.")
        }

        let command = CommandEnvelope(
            commandId: "query-window-by-title",
            command: .query,
            application: "com.apple.TextEdit",
            locator: Locator(criteria: [
                Criterion(attribute: "AXRole", value: "AXWindow"),
                Criterion(attribute: "AXTitle", value: title),
            ]))

        let response = try await self.runQuery(command: command, encoder: JSONEncoder())
        #expect(response.success)
        #expect(response.data?.attributes?["AXTitle"]?.stringValue == title)
    }

    @Test(.tags(.automation))
    func `Search elements by role`() async throws {
        await closeTextEdit()
        try await Task.sleep(for: .milliseconds(500))

        _ = try await setupTextEditAndGetInfo()
        defer {
            if let app = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").first {
                app.terminate()
            }
        }

        try await Task.sleep(for: .seconds(1))

        let command = CommandEnvelope(
            commandId: "test-search-buttons",
            command: .query,
            application: "TextEdit",
            debugLogging: true,
            locator: Locator(criteria: [Criterion(attribute: "AXRole", value: "AXButton")]),
            outputFormat: .verbose)

        let encoder = JSONEncoder()
        let jsonData = try encoder.encode(command)
        guard let jsonString = String(data: jsonData, encoding: String.Encoding.utf8) else {
            throw TestError.generic("Failed to create JSON")
        }

        let result = try runAXORCCommand(arguments: [jsonString])
        #expect(result.exitCode == 0)

        guard let output = result.output,
              let responseData = output.data(using: String.Encoding.utf8)
        else {
            throw TestError.generic("No output")
        }

        let response = try JSONDecoder().decode(QueryResponse.self, from: responseData)

        #expect(response.success)

        if let data = response.data, let attributes = data.attributes {
            if let role = attributes["AXRole"]?.anyValue as? String {
                #expect(role == "AXButton", "Should find button elements")
            }
        }
    }

    @Test(.tags(.automation))
    func `Describe element hierarchy`() async throws {
        await closeTextEdit()
        try await Task.sleep(for: .milliseconds(500))

        _ = try await setupTextEditAndGetInfo()
        defer {
            if let app = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").first {
                app.terminate()
            }
        }

        try await Task.sleep(for: .seconds(1))

        let command = CommandEnvelope(
            commandId: "test-describe",
            command: .describeElement,
            application: "TextEdit",
            debugLogging: true,
            locator: Locator(criteria: [Criterion(attribute: "AXRole", value: "AXApplication")]),
            maxElements: 3,
            outputFormat: .verbose)

        let encoder = JSONEncoder()
        let jsonData = try encoder.encode(command)
        guard let jsonString = String(data: jsonData, encoding: String.Encoding.utf8) else {
            throw TestError.generic("Failed to create JSON")
        }

        let result = try runAXORCCommand(arguments: [jsonString])
        #expect(result.exitCode == 0)

        guard let output = result.output,
              let responseData = output.data(using: String.Encoding.utf8)
        else {
            throw TestError.generic("No output")
        }

        let response = try JSONDecoder().decode(QueryResponse.self, from: responseData)

        #expect(response.success)
        #expect(response.data != nil)

        if let data = response.data, let attributes = data.attributes {
            if let role = attributes["AXRole"]?.anyValue as? String {
                #expect(role == "AXApplication", "Should find application element")
            }
        }
    }

    @Test(.tags(.automation))
    func `Set and verify text in TextEdit`() async throws {
        try await withFreshTextEdit { encoder in
            try await self.setText("Hello from AXorcist tests!", encoder: encoder)
            let response = try await self.queryTextArea(encoder: encoder)
            #expect(response.success)
            if let data = response.data,
               let value = data.attributes?["AXValue"]?.anyValue as? String
            {
                #expect(value.contains("Hello from AXorcist tests!"), "Should find the text we set")
            }
        }
    }

    @Test(.tags(.automation))
    func `Extract text from TextEdit window`() async throws {
        try await withFreshTextEdit { encoder in
            try await self.setText(
                "This is test content.\nIt has multiple lines.\nExtract this text.",
                encoder: encoder)
            let response = try await self.extractWindowText(encoder: encoder)
            #expect(response.success)
            self.assertExtractedText(response)
        }
    }
}

// MARK: - Helper Extensions

extension ElementSearchTests {
    private func withFreshTextEdit(_ action: (JSONEncoder) async throws -> Void) async throws {
        await closeTextEdit()
        try await Task.sleep(for: .milliseconds(500))
        _ = try await setupTextEditAndGetInfo()
        defer {
            if let app = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").first {
                app.terminate()
            }
        }
        try await Task.sleep(for: .seconds(1))
        let encoder = JSONEncoder()
        try await action(encoder)
    }

    private func setText(_ text: String, encoder: JSONEncoder) async throws {
        let command = CommandEnvelope(
            commandId: "set-text",
            command: .performAction,
            application: "TextEdit",
            debugLogging: true,
            locator: Locator(criteria: [Criterion(attribute: "AXRole", value: "AXTextArea")]),
            actionName: "AXSetValue",
            actionValue: .string(text))

        try await execute(command: command, encoder: encoder)
    }

    private func queryTextArea(encoder: JSONEncoder) async throws -> QueryResponse {
        let command = CommandEnvelope(
            commandId: "query-text",
            command: .query,
            application: "TextEdit",
            debugLogging: true,
            locator: Locator(criteria: [Criterion(attribute: "AXRole", value: "AXTextArea")]),
            outputFormat: .verbose)
        return try await self.runQuery(command: command, encoder: encoder)
    }

    private func extractWindowText(encoder: JSONEncoder) async throws -> QueryResponse {
        let command = CommandEnvelope(
            commandId: "extract-text-window",
            command: .extractText,
            application: "TextEdit",
            debugLogging: true,
            locator: Locator(criteria: [Criterion(attribute: "AXRole", value: "AXWindow")]),
            outputFormat: .textContent)
        return try await self.runQuery(command: command, encoder: encoder)
    }

    private func execute(command: CommandEnvelope, encoder: JSONEncoder) async throws {
        let data = try encoder.encode(command)
        guard let jsonString = String(data: data, encoding: .utf8) else {
            throw TestError.generic("Failed to create JSON")
        }
        let result = try runAXORCCommand(arguments: [jsonString])
        #expect(result.exitCode == 0)
    }

    private func runQuery(command: CommandEnvelope, encoder: JSONEncoder) async throws -> QueryResponse {
        let data = try encoder.encode(command)
        guard let jsonString = String(data: data, encoding: .utf8) else {
            throw TestError.generic("Failed to create JSON")
        }
        let result = try runAXORCCommand(arguments: [jsonString])
        #expect(result.exitCode == 0)
        guard let output = result.output,
              let responseData = output.data(using: .utf8)
        else {
            throw TestError.generic("No output")
        }
        return try JSONDecoder().decode(QueryResponse.self, from: responseData)
    }

    private func assertExtractedText(_ response: QueryResponse) {
        if let data = response.data, let attributes = data.attributes {
            if let extractedText = attributes["extractedText"]?.anyValue as? String {
                #expect(extractedText.contains("This is test content"), "Should extract the test content")
                #expect(extractedText.contains("multiple lines"), "Should extract multiple lines")
            } else if let value = attributes["AXValue"]?.anyValue as? String {
                #expect(value.contains("This is test content"), "Should extract the test content")
                #expect(value.contains("multiple lines"), "Should extract multiple lines")
            }
        }
    }
}

// SpecificCriterionMatchers.swift - Specific criterion matching functions

import Foundation

// MARK: - Specific Criterion Matchers

@MainActor
func matchPidCriterion(element: Element, expectedValue: String, elementDescriptionForLog: String) -> Bool {
    let expectedPid = expectedValue
    if element.role() == AXRoleNames.kAXApplicationRole {
        guard let actualPidT = element.pid() else {
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .debug,
                message: "SC/PID: \(elementDescriptionForLog) (app role) failed to provide PID. No match."))
            return false
        }
        if String(actualPidT) == expectedPid {
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .debug,
                message: "SC/PID: \(elementDescriptionForLog) (app role) PID \(actualPidT) " +
                    "MATCHES expected \(expectedPid)."))
            return true
        } else {
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .debug,
                message: "SC/PID: \(elementDescriptionForLog) (app role) PID \(actualPidT) " +
                    "MISMATCHES expected \(expectedPid)."))
            return false
        }
    }
    guard let actualPidT = element.pid() else {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/PID: \(elementDescriptionForLog) failed to provide PID. No match."))
        return false
    }
    let actualPidString = String(actualPidT)
    if actualPidString == expectedPid {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/PID: \(elementDescriptionForLog) PID \(actualPidString) " +
                "MATCHES expected \(expectedPid)."))
        return true
    } else {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/PID: \(elementDescriptionForLog) PID \(actualPidString) " +
                "MISMATCHES expected \(expectedPid)."))
        return false
    }
}

@MainActor
func matchIsIgnoredCriterion(element: Element, expectedValue: String, elementDescriptionForLog: String) -> Bool {
    let actualIsIgnored: Bool = element.isIgnored()
    let expectedBool = (expectedValue.lowercased() == "true")
    if actualIsIgnored == expectedBool {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/IsIgnored: \(elementDescriptionForLog) actual ('\(actualIsIgnored)') " +
                "MATCHES expected ('\(expectedBool)')."))
        return true
    } else {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/IsIgnored: \(elementDescriptionForLog) actual ('\(actualIsIgnored)') " +
                "MISMATCHES expected ('\(expectedBool)')."))
        return false
    }
}

@MainActor
func matchDomClassListCriterion(
    element: Element,
    expectedValue: String,
    matchType: JSONPathHintComponent.MatchType,
    elementDescriptionForLog: String) -> Bool
{
    guard let domClassListValue: Any = element.attribute(Attribute(AXAttributeNames.kAXDOMClassListAttribute)) else {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/DOMClass: \(elementDescriptionForLog) attribute was nil. No match."))
        return false
    }

    let matcher = DOMClassMatcher(
        value: domClassListValue,
        matchType: matchType,
        expectedValue: expectedValue,
        elementDescription: elementDescriptionForLog)
    return matcher.evaluate()
}

private struct DOMClassMatcher {
    let value: Any
    let matchType: JSONPathHintComponent.MatchType
    let expectedValue: String
    let elementDescription: String

    func evaluate() -> Bool {
        if let classArray = self.value as? [String] {
            return self.evaluateArray(classArray)
        }
        if let classString = self.value as? String {
            let components = classString.split(separator: " ").map(String.init)
            return self.evaluateArray(components, joinedString: classString)
        }

        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/DOMClass: \(self.elementDescription) attribute was not [String] or String " +
                "(type: \(type(of: self.value))). No match."))
        return false
    }

    private func evaluateArray(_ array: [String], joinedString: String? = nil) -> Bool {
        let match = self.match(array: array, joinedString: joinedString)
        self.logResult(array: array, joinedString: joinedString, matchFound: match)
        return match
    }

    private func match(array: [String], joinedString: String?) -> Bool {
        switch self.matchType {
        case .exact:
            return array.contains(self.expectedValue)
        case .contains:
            return (joinedString ?? array.joined(separator: " ")).localizedCaseInsensitiveContains(self.expectedValue)
        case .containsAny:
            let expectedParts = self.expectedValue
                .split(separator: ",")
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            if let joined = joinedString {
                return expectedParts.contains { joined.localizedCaseInsensitiveContains($0) }
            }
            return array.contains { actual in
                expectedParts.contains { expected in actual.localizedCaseInsensitiveContains(expected) }
            }
        case .prefix:
            return array.contains { $0.hasPrefix(self.expectedValue) }
        case .suffix:
            return array.contains { $0.hasSuffix(self.expectedValue) }
        case .regex:
            self.logRegexHint(isArray: joinedString == nil)
            return array.contains { classEntry in
                classEntry.range(of: self.expectedValue, options: .regularExpression) != nil
            }
        }
    }

    private func logRegexHint(isArray: Bool) {
        let typeDescription = isArray ? "array of classes" : "space-separated class string"
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/DOMClass: Regex matching for \(typeDescription). " +
                "Element: \(self.elementDescription) Expected: \(self.expectedValue)."))
    }

    private func logResult(array: [String], joinedString: String?, matchFound: Bool) {
        let representation = joinedString ?? array.description
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/DOMClass: \(self.elementDescription) match type '\(self.matchType.rawValue)' " +
                "with '\(self.expectedValue)' resolved to \(matchFound). Classes: \(representation)"))
        let resultText = matchFound ? "MATCHED" : "MISMATCHED"
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "SC/DOMClass: \(self.elementDescription) \(resultText) expected '\(self.expectedValue)' " +
                "with type '\(self.matchType.rawValue)'."))
    }
}

// SpecificAttributeMatchers.swift - Contains specific helper functions for attribute matching.

import ApplicationServices
import Foundation

// Assumes Element, Attribute, AXMiscConstants.computedNameAttributeKey, AXMiscConstants.kAXNotAvailableString,
// AXAttributeNames.kAXRoleAttribute, AXAttributeNames.kAXEnabledAttribute,
// AXAttributeNames.kAXFocusedAttribute, AXAttributeNames.kAXHiddenAttribute,
// AXAttributeNames.kAXElementBusyAttribute, AXMiscConstants.isIgnoredAttributeKey, AXAttributeNames.kAXMainAttribute,
// AXAttributeNames.kAXActionNamesAttribute, AXAttributeNames.kAXAllowedValuesAttribute,
// AXAttributeNames.kAXChildrenAttribute are available.
// Assumes decodeExpectedArray (from ValueParser or similar) and
// getComputedAttributes (from AttributeHelpers) are available.

@MainActor
func matchStringAttribute(
    element: Element,
    key: String,
    expectedValueString: String,
    depth: Int) -> Bool
{
    if let currentValue = element.attribute(Attribute<String>(key)) {
        if currentValue != expectedValueString {
            axDebugLog(
                "attributesMatch [D\(depth)]: Attribute '\(key)' expected '\(expectedValueString)', " +
                    "but found '\(currentValue)'. No match.",
                file: #file,
                function: #function,
                line: #line)
            return false
        }
        return true
    } else {
        if expectedValueString.lowercased() == "nil" ||
            expectedValueString == AXMiscConstants.kAXNotAvailableString ||
            expectedValueString.isEmpty
        {
            axDebugLog(
                "attributesMatch [D\(depth)]: Attribute '\(key)' not found, but expected value " +
                    "('\(expectedValueString)') suggests absence is OK. Match for this key.",
                file: #file,
                function: #function,
                line: #line)
            return true
        } else {
            axDebugLog(
                "attributesMatch [D\(depth)]: Attribute '\(key)' " +
                    "(expected '\(expectedValueString)') not found or not convertible to String. No match.",
                file: #file,
                function: #function,
                line: #line)
            return false
        }
    }
}

@MainActor
func matchArrayAttribute(
    element: Element,
    key: String,
    expectedValueString: String,
    depth: Int) -> Bool
{
    guard let expectedArray = decodeExpectedArray(fromString: expectedValueString) else {
        logArrayAttributeWarning(
            "Could not decode expected array string '\(expectedValueString)' for attribute '\(key)'.",
            depth: depth)
        return false
    }

    switch fetchArrayAttribute(element: element, key: key) {
    case .unsupported:
        logArrayAttributeWarning(
            "Unknown array key '\(key)'. Extend matchArrayAttribute for this key.",
            depth: depth)
        return false
    case .missing:
        return handleMissingArrayAttribute(
            expectedArray: expectedArray,
            expectedValueString: expectedValueString,
            key: key,
            depth: depth)
    case let .value(actual):
        guard Set(actual) == Set(expectedArray) else {
            axDebugLog(
                "matchArrayAttribute [D\(depth)]: Array Attribute '\(key)' expected '\(expectedArray)', " +
                    "but found '\(actual)'. Sets differ. No match.",
                file: #file,
                function: #function,
                line: #line)
            return false
        }
        return true
    }
}

private enum ArrayAttributeFetchResult {
    case value([String])
    case missing
    case unsupported
}

@MainActor
private func fetchArrayAttribute(element: Element, key: String) -> ArrayAttributeFetchResult {
    switch key {
    case AXAttributeNames.kAXActionNamesAttribute:
        return element.supportedActions().map(ArrayAttributeFetchResult.value) ?? .missing
    case AXAttributeNames.kAXAllowedValuesAttribute:
        let value = element.attribute(Attribute<[String]>(key))
        return value.map(ArrayAttributeFetchResult.value) ?? .missing
    case AXAttributeNames.kAXChildrenAttribute:
        let children = element.children()?.map { $0.role() ?? "UnknownRole" }
        return children.map(ArrayAttributeFetchResult.value) ?? .missing
    default:
        return .unsupported
    }
}

@MainActor
private func handleMissingArrayAttribute(
    expectedArray: [String],
    expectedValueString: String,
    key: String,
    depth: Int) -> Bool
{
    if expectedArray.isEmpty {
        axDebugLog(
            "matchArrayAttribute [D\(depth)]: Array Attribute '\(key)' not found, " +
                "but expected array was empty. Match for this key.",
            file: #file,
            function: #function,
            line: #line)
        return true
    }
    axDebugLog(
        "matchArrayAttribute [D\(depth)]: Array Attribute '\(key)' " +
            "(expected '\(expectedValueString)') not found in element. No match.",
        file: #file,
        function: #function,
        line: #line)
    return false
}

private func logArrayAttributeWarning(_ message: String, depth: Int) {
    axWarningLog(
        "matchArrayAttribute [D\(depth)]: \(message)",
        file: #file,
        function: #function,
        line: #line)
}

@MainActor
func matchBooleanAttribute(
    element: Element,
    key: String,
    expectedValueString: String,
    depth: Int) -> Bool
{
    var currentBoolValue: Bool?

    switch key {
    case AXAttributeNames.kAXEnabledAttribute: currentBoolValue = element.isEnabled()
    case AXAttributeNames.kAXFocusedAttribute: currentBoolValue = element.isFocused()
    case AXAttributeNames.kAXHiddenAttribute: currentBoolValue = element.isHidden()
    case AXAttributeNames.kAXElementBusyAttribute: currentBoolValue = element.isElementBusy()
    case AXMiscConstants.isIgnoredAttributeKey: currentBoolValue = element.isIgnored()
    case AXAttributeNames.kAXMainAttribute: currentBoolValue = element.attribute(Attribute<Bool>(key))
    default:
        axWarningLog(
            "matchBooleanAttribute [D\(depth)]: Unknown boolean key '\(key)'. This should not happen.",
            file: #file,
            function: #function,
            line: #line)
        return false
    }

    if let actualBool = currentBoolValue {
        let expectedBool = expectedValueString.lowercased() == "true"
        if actualBool != expectedBool {
            axDebugLog(
                "attributesMatch [D\(depth)]: Boolean Attribute '\(key)' expected '\(expectedBool)', " +
                    "but found '\(actualBool)'. No match.",
                file: #file,
                function: #function,
                line: #line)
            return false
        }
        return true
    } else {
        axDebugLog(
            "attributesMatch [D\(depth)]: Boolean Attribute '\(key)' " +
                "(expected '\(expectedValueString)') not found in element. No match.",
            file: #file,
            function: #function,
            line: #line)
        return false
    }
}

@MainActor
func matchComputedNameAttributes(
    element: Element,
    computedNameEquals: String?,
    computedNameContains: String?,
    depth: Int) async -> Bool
{
    if computedNameEquals == nil, computedNameContains == nil {
        return true // No computed name criteria to match, so this part passes.
    }

    let computedAttrs = await getComputedAttributes(for: element)
    let computedNameKey = AXMiscConstants.computedNameAttributeKey
    if let currentComputedName = computedAttrs[computedNameKey]?.value.stringValue {
        if let equals = computedNameEquals {
            if currentComputedName != equals {
                axDebugLog(
                    "matchComputedNameAttributes [D\(depth)]: ComputedName '\(currentComputedName)' " +
                        "!= '\(equals)'. No match.",
                    file: #file,
                    function: #function,
                    line: #line)
                return false
            }
        }
        if let contains = computedNameContains {
            if !currentComputedName.localizedCaseInsensitiveContains(contains) {
                axDebugLog(
                    "matchComputedNameAttributes [D\(depth)]: ComputedName '\(currentComputedName)' " +
                        "does not contain '\(contains)'. No match.",
                    file: #file,
                    function: #function,
                    line: #line)
                return false
            }
        }
        return true
    } else {
        if computedNameEquals != nil || computedNameContains != nil {
            let equalsStr = computedNameEquals ?? "nil"
            let containsStr = computedNameContains ?? "nil"
            axDebugLog(
                "matchComputedNameAttributes [D\(depth)]: Locator requires ComputedName " +
                    "(equals: \(equalsStr), contains: \(containsStr)), " +
                    "but element has none or it's not a string. No match.",
                file: #file,
                function: #function,
                line: #line)
            return false
        }
        return true
    }
}

import AppKit
import Foundation
import os
import Testing
@testable import AXorcist

@Suite("Workspace application monitor", .timeLimit(.minutes(1)))
@MainActor
struct WorkspaceApplicationMonitorTests {
    @Test(arguments: MetadataRead.initialReads)
    private func `blocked metadata leaves MainActor and stop responsive`(_ read: MetadataRead) async {
        let gate = MetadataGate(read: read)
        let probe = ApplicationMetadataProbe()
        let application = MonitorApplication(instance: "blocked", pid: 42, ready: false, probe: probe, gate: gate)
        let workspace = MonitorWorkspace(applications: [application])
        let monitor = AXWorkspaceApplicationMonitor(workspace: workspace, runningApplications: \.applications)
        var launches: [pid_t] = []
        monitor.start(onLaunch: { launches.append($0) }, onTermination: { _ in })
        await gate.waitUntilEntered()

        // A main-thread getter reports the regression and returns instead of deadlocking the test runner.
        #expect(gate.isBlocked, "The metadata read must still be held while MainActor makes progress")
        monitor.stop()
        #expect(monitor.runningProcessIdentifiers.isEmpty)
        let launchesAtStop = launches
        gate.release()
        workspace.applications = []
        monitor.start(onLaunch: { launches.append($0) }, onTermination: { _ in })
        await workspace.flushMetadata()
        #expect(launches == launchesAtStop)
        monitor.stop()
    }

    @Test(arguments: MetadataRead.initialReads)
    private func `blocked metadata cannot revive the previous session`(_ read: MetadataRead) async {
        let gate = MetadataGate(read: read)
        let probe = ApplicationMetadataProbe()
        let previous = MonitorApplication(instance: "previous", pid: 41, ready: false, probe: probe, gate: gate)
        let replacement = MonitorApplication(instance: "replacement", pid: 42, probe: probe)
        let workspace = MonitorWorkspace(applications: [previous])
        let monitor = AXWorkspaceApplicationMonitor(workspace: workspace, runningApplications: \.applications)
        var oldLaunches: [pid_t] = []
        var newLaunches: [pid_t] = []
        monitor.start(onLaunch: { oldLaunches.append($0) }, onTermination: { _ in })
        await gate.waitUntilEntered()
        monitor.stop()
        let launchesAtStop = oldLaunches
        workspace.applications = [replacement]
        monitor.start(onLaunch: { newLaunches.append($0) }, onTermination: { _ in })
        await drainMainQueue()

        #expect(gate.isBlocked)
        #expect(monitor.runningProcessIdentifiers.isEmpty)
        gate.release()
        await workspace.flushMetadata()
        #expect(oldLaunches == launchesAtStop)
        #expect(newLaunches == [42])
        #expect(monitor.runningProcessIdentifiers == [42])
        monitor.stop()
    }

    @Test(arguments: MetadataRead.initialReads, [false, true])
    private func `blocked metadata cannot escape membership removal`(
        _ read: MetadataRead,
        sameIdentity: Bool) async
    {
        let gate = MetadataGate(read: read)
        let probe = ApplicationMetadataProbe()
        let previous = MonitorApplication(instance: "previous", pid: 42, ready: false, probe: probe, gate: gate)
        let replacement = MonitorApplication(
            instance: sameIdentity ? "previous" : "replacement", pid: 42, ready: false, probe: probe)
        let workspace = MonitorWorkspace(applications: [previous])
        let monitor = AXWorkspaceApplicationMonitor(workspace: workspace, runningApplications: \.applications)
        var events: [String] = []
        monitor.start(onLaunch: { events.append("launch:\($0)") }, onTermination: { events.append("terminate:\($0)") })
        await gate.waitUntilEntered()
        await drainMainQueue()
        let initialEvents = events
        if sameIdentity {
            workspace.applications = []
        }
        workspace.applications = [replacement]
        await drainMainQueue()

        #expect(gate.isBlocked)
        #expect(monitor.runningProcessIdentifiers.isEmpty)
        let removedEvents = initialEvents.isEmpty ? [] : ["launch:42", "terminate:42"]
        #expect(events == removedEvents)
        gate.release()
        await workspace.flushMetadata()
        #expect(events == removedEvents + ["launch:42"])
        previous.finishLaunching()
        previous.finishLaunching()
        await workspace.flushMetadata()
        #expect(events == removedEvents + ["launch:42"])
        replacement.finishLaunching()
        replacement.finishLaunching()
        await workspace.flushMetadata()
        #expect(events == removedEvents + ["launch:42", "launch:42"])
        #expect(monitor.runningProcessIdentifiers == [42])
        monitor.stop()
    }

    @Test(arguments: [MetadataRead.readinessCheck, .readinessRecheck])
    private func `readiness check subscribe recheck closes both transition races`(_ read: MetadataRead) async {
        let gate = MetadataGate(read: read)
        let probe = ApplicationMetadataProbe()
        let application = MonitorApplication(instance: "slow", pid: 42, ready: false, probe: probe, gate: gate)
        let workspace = MonitorWorkspace(applications: [application])
        let monitor = AXWorkspaceApplicationMonitor(workspace: workspace, runningApplications: \.applications)
        var launches: [pid_t] = []
        monitor.start(onLaunch: { launches.append($0) }, onTermination: { _ in })
        await gate.waitUntilEntered()
        probe.insideCallback = true
        application.finishLaunching()
        application.finishLaunching()
        probe.insideCallback = false
        #expect(gate.isBlocked)
        gate.release()
        await workspace.flushMetadata()

        #expect(launches == [42, 42])
        #expect(probe.reentrantMetadataReads == 0)
        monitor.stop()
    }

    @Test
    func `readiness notification defers its blocked getter and stop discards the result`() async {
        let gate = MetadataGate(read: .readinessNotification)
        let probe = ApplicationMetadataProbe()
        let application = MonitorApplication(instance: "slow", pid: 42, ready: false, probe: probe, gate: gate)
        let workspace = MonitorWorkspace(applications: [application])
