@MainActor
private final class MonitorWorkspace: NSObject {
    private var storedApplications: [NSRunningApplication]

    @objc dynamic nonisolated var applications: [NSRunningApplication] {
        get { MainActor.assumeIsolated { self.storedApplications } }
        set { MainActor.assumeIsolated { self.storedApplications = newValue } }
    }

    @MainActor
    init(applications: [NSRunningApplication]) {
        self.storedApplications = applications
        super.init()
    }

    func replaceWithLifetimeApplication(
        probe: ApplicationMetadataProbe,
        lifetime: ApplicationLifetimeProbe) -> WeakMonitorApplication
    {
        autoreleasepool {
            let application = MonitorApplication(
                instance: "same",
                pid: 42,
                ready: false,
                probe: probe,
                lifetime: lifetime)
            self.applications = [application]
            return WeakMonitorApplication(application)
        }
    }

    /// A synthetic invalid-PID member is an observable fence behind earlier metadata work.
    /// No production queue/test hook or timing assumption is needed.
    func flushMetadata() async {
        await drainMainQueue()
        let read = AsyncStream<Void>.makeStream()
        let fence = MonitorApplication(instance: UUID().uuidString, pid: -1, probe: ApplicationMetadataProbe()) {
            DispatchQueue.main.async { read.continuation.yield(()) }
        }
        self.applications.append(fence)
        var iterator = read.stream.makeAsyncIterator()
        _ = await iterator.next()
        self.applications.removeAll { $0 === fence }
        await drainMainQueue()
    }

    func countReconcileEqualities(
        _ applications: [NSRunningApplication],
        probe: ApplicationMetadataProbe) async -> Int
    {
        await withCheckedContinuation { continuation in
            DispatchQueue.main.async {
                probe.equalityCalls = 0
                self.applications = applications
                // Enqueued before reconcile can schedule metadata results back to the main queue.
                DispatchQueue.main.async { continuation.resume(returning: probe.equalityCalls) }
            }
        }
    }
}

@MainActor
private final class WeakMonitorApplication {
    weak var value: MonitorApplication?

    init(_ application: MonitorApplication) {
        self.value = application
    }
}

private final nonisolated class MonitorApplication: NSRunningApplication, @unchecked Sendable {
    // Foundation may try to unregister during super.deinit, after Swift stored properties are gone.
    // Keep the baseline regression an assertion failure instead of calling AppKit on that dead state.
    private static let deallocating = OSAllocatedUnfairLock(initialState: Set<ObjectIdentifier>())
    private let instance: String
    private let pid: pid_t
    private let probe: ApplicationMetadataProbe
    private let ready: OSAllocatedUnfairLock<Bool>
    private let gate: MetadataGate?
    private let lifetime: ApplicationLifetimeProbe?
    private let constantHash: Bool
    private let onPIDRead: (@Sendable () -> Void)?

    @MainActor
    init(
        instance: String,
        pid: pid_t,
        ready: Bool = true,
        probe: ApplicationMetadataProbe,
        gate: MetadataGate? = nil,
        lifetime: ApplicationLifetimeProbe? = nil,
        constantHash: Bool = false,
        onPIDRead: (@Sendable () -> Void)? = nil)
    {
        self.instance = instance
        self.pid = pid
        self.ready = OSAllocatedUnfairLock(initialState: ready)
        self.probe = probe
        self.gate = gate
        self.lifetime = lifetime
        self.constantHash = constantHash
        self.onPIDRead = onPIDRead
        super.init()
        _ = Self.deallocating.withLock { $0.remove(ObjectIdentifier(self)) }
    }

    deinit {
        if let lifetime = self.lifetime {
            _ = Self.deallocating.withLock { $0.insert(ObjectIdentifier(self)) }
            lifetime.deallocated()
        }
    }

    override func addObserver(
        _ observer: NSObject,
        forKeyPath keyPath: String,
        options: NSKeyValueObservingOptions = [],
        context: UnsafeMutableRawPointer?)
    {
        super.addObserver(observer, forKeyPath: keyPath, options: options, context: context)
        self.lifetime?.registered()
    }

    override func removeObserver(_ observer: NSObject, forKeyPath keyPath: String, context: UnsafeMutableRawPointer?) {
        guard !Self.deallocating.withLock({ $0.contains(ObjectIdentifier(self)) }) else { return }
        super.removeObserver(observer, forKeyPath: keyPath, context: context)
        self.lifetime?.removed()
    }

    override var processIdentifier: pid_t {
        self.probe.recordRead()
        self.gate?.visit(pid: true)
        self.onPIDRead?()
        return self.pid
    }

    override var isTerminated: Bool {
        self.probe.recordRead(termination: true)
        return false
    }

    override var isFinishedLaunching: Bool {
        self.probe.recordRead()
        let ready = self.ready.withLock { $0 }
        self.gate?.visit(pid: false)
        return ready
    }

    @MainActor
    func finishLaunching() {
        let key = #keyPath(NSRunningApplication.isFinishedLaunching)
        self.willChangeValue(forKey: key)
        self.ready.withLock { $0 = true }
        self.didChangeValue(forKey: key)
    }

    override var hash: Int {
        self.constantHash ? 1 : self.instance.hashValue
    }

    override func isEqual(_ object: Any?) -> Bool {
        self.probe.recordEquality()
        return (object as? MonitorApplication)?.instance == self.instance
    }
}

import Foundation

private final nonisolated class PipeStreamBuffer: @unchecked Sendable {
    private let queue = DispatchQueue(
        label: "axorcist.tests.pipe-stream.\(UUID().uuidString)",
        qos: .userInitiated)
    private nonisolated(unsafe) var data = Data()

    nonisolated func append(_ chunk: Data) {
        self.queue.async {
            self.data.append(chunk)
        }
    }

    nonisolated func snapshot() -> Data {
        self.queue.sync { self.data }
    }
}

@discardableResult
nonisolated func startStreaming(pipe: Pipe) -> () -> Data {
    let buffer = PipeStreamBuffer()
    let group = DispatchGroup()

    group.enter()
    pipe.fileHandleForReading.readabilityHandler = { handle in
        let chunk = handle.availableData
        if chunk.isEmpty {
            handle.readabilityHandler = nil
            group.leave()
            return
        }
        buffer.append(chunk)
    }

    return {
        group.wait()
        return buffer.snapshot()
    }
}

// Element+Actions.swift - Action-related methods for Element

import ApplicationServices
import Foundation

// GlobalAXLogger should be available

/// Action-related extension for Element
extension Element {
    // MARK: - Actions

    @MainActor
    public func isActionSupported(_ actionName: String) -> Bool {
        self.supportedActions()?.contains(actionName) ?? false
    }

    @MainActor
    @discardableResult
    public func performAction(_ actionName: Attribute<String>) throws -> Element {
        try self.performAction(actionName.rawValue)
    }

    @MainActor
    @discardableResult
    public func performAction(_ actionName: String) throws -> Element {
        try self.performAction(actionName, using: AXUIElementPerformAction)
    }

    @MainActor
    @discardableResult
    func performAction(
        _ actionName: String,
        using performer: (AXUIElement, CFString) -> AXError) throws -> Element
    {
        let description = GlobalAXLogger.shared.isLoggingEnabled
            ? self.briefDescription(option: .smart)
            : nil
        if let description {
            axDebugLog("Attempting to perform action '\(actionName)' on element: \(description)")
        }

        try performer(self.underlyingElement, actionName as CFString).throwIfError()

        if let description {
            axInfoLog("Successfully performed action '\(actionName)' on element: \(description)")
        }
        return self
    }

    /// Modern enum-based performAction method with cleaner syntax
    /// Example: try element.performAction(.raise)
    @MainActor
    @discardableResult
    public func performAction(_ action: AXAction) throws -> Element {
        try self.performAction(action.rawValue)
    }
}

// Element+ApplicationActions.swift - Application-specific actions for Element

import ApplicationServices
import Foundation

extension Element {
    /// Helper to set a boolean attribute value.
    /// Returns true on success, false on failure.
    @MainActor
    private func setBooleanAttribute(_ attributeName: String, value: Bool) -> Bool {
        let cfValue: CFBoolean = CFConstants.cfBoolean(from: value)
        let error = AXUIElementSetAttributeValue(underlyingElement, attributeName as CFString, cfValue)
        if error != AXError.success {
            axErrorLog(
                "Failed to set attribute \(attributeName) to \(value). "
                    + "Error: \(error.rawValue) - \(error.localizedDescription)")
            return false
        }
        axDebugLog("Successfully set attribute \(attributeName) to \(value).")
        return true
    }

    /// Activates the application represented by this element by bringing it to the front.
    /// This is typically called on an Element representing an application.
    /// - Returns: `true` if the action was successful, `false` otherwise.
    @MainActor
    public func activate() -> Bool {
        axDebugLog("Attempting to activate application (element: \(self.briefDescription()))")
        // Try to set kAXFrontmostAttribute. If not settable or fails, fallback to kAXRaiseAction.
        guard isAttributeSettable(named: AXAttributeNames.kAXFrontmostAttribute) else {
            axWarningLog(
                "kAXFrontmostAttribute is not settable for element \(self.briefDescription()). "
                    + "Falling back to .raise action.")
            // Use the throwing performAction and handle potential errors, or make it non-throwing if that's the design.
            // For now, assuming it should succeed or log internally, returning bool.
            do {
                try self.performAction(.raise) // Fallback to raise action
                return true // If performAction succeeded
            } catch {
                axErrorLog(
                    "Fallback action .raise failed for element \(self.briefDescription()): "
                        + error.localizedDescription)
                return false // If performAction failed
            }
        }
        let success = self.setBooleanAttribute(AXAttributeNames.kAXFrontmostAttribute, value: true)
        if !success {
            axWarningLog(
                "Setting kAXFrontmostAttribute failed for \(self.briefDescription()). "
                    + "Falling back to .raise action.")
            // Similar handling for the fallback action
            do {
                try self.performAction(.raise)
                return true
            } catch {
                axErrorLog(
                    "Fallback action .raise failed after setBooleanAttribute failed for "
                        + "\(self.briefDescription()): \(error.localizedDescription)")
                return false
            }
        }
        return true
    }

    /// Hides the application represented by this element.
    /// This is typically called on an Element representing an application.
    /// - Returns: `true` if the action was successful, `false` otherwise.
    @MainActor
    public func hideApplication() -> Bool {
        axDebugLog("Attempting to hide application (element: \(self.briefDescription()))")
        if !isAttributeSettable(named: AXAttributeNames.kAXHiddenAttribute) {
            axWarningLog(
                "Attribute \(AXAttributeNames.kAXHiddenAttribute) is not settable for "
                    + "element \(self.briefDescription()).")
            return false
        }
        return self.setBooleanAttribute(AXAttributeNames.kAXHiddenAttribute, value: true)
    }

    /// Unhides the application represented by this element.
    /// This is typically called on an Element representing an application.
    /// - Returns: `true` if the action was successful, `false` otherwise.
    @MainActor
    public func unhideApplication() -> Bool {
        axDebugLog("Attempting to unhide application (element: \(self.briefDescription()))")
        if !isAttributeSettable(named: AXAttributeNames.kAXHiddenAttribute) {
            axWarningLog(
                "Attribute \(AXAttributeNames.kAXHiddenAttribute) is not settable for "
                    + "element \(self.briefDescription()).")
            return false
        }
        return self.setBooleanAttribute(AXAttributeNames.kAXHiddenAttribute, value: false)
    }
}

import AppKit // For NSRunningApplication & NSValue
import ApplicationServices
import Foundation

/// Extension providing action execution handlers for AXorcist.
///
/// This extension handles:
/// - Performing accessibility actions on UI elements
/// - Action error handling
/// - Setting element values (text, numeric, selection)
/// - Complex action coordination and validation
/// - Integration with element discovery and targeting
@MainActor
extension AXorcist {
    // MARK: - Perform Action Handler

    public func handlePerformAction(command: PerformActionCommand) -> AXResponse {
        self.handlePerformAction(command: command, traversalOptions: .snapshotDefaults())
    }

    public func handlePerformAction(
        command: PerformActionCommand,
        traversalOptions: AXTraversalOptions) -> AXResponse
    {
        self.logPerformActionStart(command)

        let element: Element
        switch resolveTargetElement(
            appIdentifier: command.appIdentifier,
            pid: command.pid,
            locator: command.locator,
            maxDepthForSearch: command.maxDepthForSearch,
            traversalOptions: traversalOptions)
        {
        case let .success(resolvedElement):
            element = resolvedElement
        case let .failure(error):
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: error.message))
            return error.response
        }

        return self.executeResolvedAction(command: command, on: element)
    }

    // MARK: - Set Focused Value Handler

    public func handleSetFocusedValue(command: SetFocusedValueCommand) -> AXResponse {
        self.handleSetFocusedValue(command: command, traversalOptions: .snapshotDefaults())
    }

    public func handleSetFocusedValue(
        command: SetFocusedValueCommand,
        traversalOptions: AXTraversalOptions) -> AXResponse
    {
        self.logSetFocusedValueStart(command)

        let element: Element
        switch resolveTargetElement(
            appIdentifier: command.appIdentifier,
            pid: command.pid,
            locator: command.locator,
            maxDepthForSearch: command.maxDepthForSearch,
            traversalOptions: traversalOptions)
        {
        case let .success(resolvedElement):
            element = resolvedElement
        case let .failure(error):
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: error.message))
            return error.response
        }

        if self.ensureFocusCapability(for: element) {
            self.setFocus(on: element)
        }
        return self.executeSetValue(value: command.value, on: element)
    }

    // MARK: - Extract Text Handler

    public func handleExtractText(command: ExtractTextCommand) -> AXResponse {
        self.handleExtractText(command: command, traversalOptions: .snapshotDefaults())
    }

    public func handleExtractText(
        command: ExtractTextCommand,
        traversalOptions: AXTraversalOptions) -> AXResponse
    {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .info,
            message: "HandleExtractText: App '\(String(describing: command.appIdentifier))', " +
                "Locator: \(command.locator), " +
                "IncludeChildren: \(String(describing: command.includeChildren)), " +
                "MaxDepth: \(String(describing: command.maxDepth))"))

        let element: Element
        switch resolveTargetElement(
            appIdentifier: command.appIdentifier,
            pid: command.pid,
            locator: command.locator,
            maxDepthForSearch: command.maxDepthForSearch,
            traversalOptions: traversalOptions)
        {
        case let .success(resolvedElement):
            element = resolvedElement
        case let .failure(error):
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: error.message))
            return error.response
        }
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "HandleExtractText: Found element: " +
                "\(element.briefDescription(option: ValueFormatOption.smart))"))

        if let textContent = getElementTextualContent(
            element: element,
            includeChildren: command.includeChildren ?? true,
            maxDepth: command.maxDepth ?? 5)
        {
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .info,
                message: "HandleExtractText: Extracted text: '\(textContent)'"))
            return .successResponse(payload: AnyCodable(TextPayload(text: textContent)))
        } else {
            let message = "HandleExtractText: No text content found for " +
                "element \(element.briefDescription(option: ValueFormatOption.smart))."
            GlobalAXLogger.shared.log(AXLogEntry(level: .info, message: message))
            return .successResponse(payload: AnyCodable(TextPayload(text: ""))) // Success, but no text
        }
    }
}

// MARK: - Shared Helpers

extension AXorcist {
    private func logPerformActionStart(_ command: PerformActionCommand) {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .info,
            message: "HandlePerformAction: App '\(String(describing: command.appIdentifier))', " +
                "Locator: \(command.locator), Action: \(command.action), " +
                "Value: \(String(describing: command.value))"))
    }

    private func logSetFocusedValueStart(_ command: SetFocusedValueCommand) {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .info,
            message: "HandleSetFocusedValue: App '\(String(describing: command.appIdentifier))', " +
                "Locator: \(command.locator), Value: '\(command.value)'"))
    }

    func executeResolvedAction(
        command: PerformActionCommand,
        on element: Element,
        performer: (Element, String) throws -> Void = { element, action in
            try element.performAction(action)
        },
        valueSetter: (Element, String) throws -> Void = { element, value in
            try element.setValue(value)
        },
        supportedActions: (Element) -> [String]? = { element in
            element.supportedActions()
        }) -> AXResponse
    {
        guard command.action == AXActionNames.kAXSetValueAction else {
            return self.executeAction(
                action: command.action,
                on: element,
                value: command.value,
                performer: performer,
                supportedActions: supportedActions)
        }

        guard let value = command.value?.value as? String else {
            let message = "HandlePerformAction: AXSetValue requires a string action_value. No value was dispatched."
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: message))
            return .errorResponse(message: message, code: .invalidParameter)
        }

        return self.executeSetValue(value: value, on: element, setter: valueSetter)
    }

    func executeAction(
        action: String,
        on element: Element,
        value: AnyCodable?,
        performer: (Element, String) throws -> Void = { element, action in
            try element.performAction(action)
        },
        supportedActions: (Element) -> [String]? = { element in
            element.supportedActions()
        }) -> AXResponse
    {
        if let actionValue = value?.value {
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .warning,
                message: "HandlePerformAction: Action value provided but not used: \(actionValue)"))
        }

        do {
            try performer(element, action)
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .info,
                message: "HandlePerformAction: Successfully performed action '\(action)'."))
            return .successResponse(
                payload: AnyCodable(["message": "Action '\(action)' performed successfully."]))
        } catch let error as AccessibilitySystemError {
            // The platform can return cannotComplete after dispatch, so classify once and never retry here.
            return self.actionFailureResponse(
                action: action,
                element: element,
                error: error,
                supportedActions: supportedActions)
        } catch {
            let errorMessage = "HandlePerformAction: Failed to perform action '\(action)'. Error: \(error)"
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: errorMessage))
            return .errorResponse(message: errorMessage, code: .actionFailed)
        }
    }

    func executeSetValue(
        value: String,
        on element: Element,
        setter: (Element, String) throws -> Void = { element, value in
            try element.setValue(value)
        }) -> AXResponse
    {
        do {
            try setter(element, value)
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .info,
                message: "Successfully set the element's AXValue attribute."))
            return .successResponse(payload: AnyCodable(["message": "Value set successfully."]))
        } catch let error as AccessibilitySystemError {
            let message = "Failed to set AXValue. Error: \(error.localizedDescription) " +
                "(AXError \(error.axError.rawValue))."
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: message))
            return .errorResponse(message: message, code: error.axError.valueResponseCode)
        } catch {
            let message = "Failed to set AXValue. Error: \(error.localizedDescription)"
            GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: message))
            return .errorResponse(message: message, code: .actionFailed)
        }
    }

    private func actionFailureResponse(
        action: String,
        element: Element,
        error: AccessibilitySystemError,
        supportedActions: (Element) -> [String]?) -> AXResponse
    {
        let summary = error.axError == .actionUnsupported
            ? "Action '\(action)' is not supported."
            : "Failed to perform action '\(action)'."
        var errorMessage = "HandlePerformAction: \(summary) " +
            "Error: \(error.localizedDescription) (AXError \(error.axError.rawValue))."
        if error.axError == .actionUnsupported {
            let availableActions = supportedActions(element) ?? []
            errorMessage += " Available actions: [\(availableActions.joined(separator: ", "))]"
        }
        GlobalAXLogger.shared.log(AXLogEntry(level: .error, message: errorMessage))
        return .errorResponse(message: errorMessage, code: error.axError.actionResponseCode)
    }

    private func ensureFocusCapability(for element: Element) -> Bool {
        if element.isAttributeSettable(named: AXAttributeNames.kAXFocusedAttribute) {
            return true
        }

        let elementDescription = GlobalAXLogger.shared.isLoggingEnabled
            ? element.briefDescription(option: .smart)
            : nil
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "HandleSetFocusedValue: Element not directly focusable by kAXFocusedAttribute, " +
                "attempting kAXPressAction."))
        do {
            try element.performAction(.press)
            GlobalAXLogger.shared.log(AXLogEntry(
                level: .debug,
                message: "HandleSetFocusedValue: Successfully pressed element to potentially gain focus."))
        } catch let error as AccessibilitySystemError where error.axError == .actionUnsupported {
            let focusError = [
                "HandleSetFocusedValue: Element \(elementDescription ?? "target") is not focusable",
                "(kAXFocusedAttribute not settable and kAXPressAction not supported).",
            ].joined(separator: " ")
            GlobalAXLogger.shared.log(AXLogEntry(level: .warning, message: focusError))
        } catch let error as AccessibilitySystemError {
            let pressError = [
                "HandleSetFocusedValue: Element \(elementDescription ?? "target") could not be pressed",
                "to potentially gain focus. Error: \(error.localizedDescription)",
                "(AXError \(error.axError.rawValue)).",
            ].joined(separator: " ")
            GlobalAXLogger.shared.log(AXLogEntry(level: .warning, message: pressError))
        } catch {
            let pressError = [
                "HandleSetFocusedValue: Element \(elementDescription ?? "target") could not be pressed",
                "to potentially gain focus. Error: \(error)",
            ].joined(separator: " ")
            GlobalAXLogger.shared.log(AXLogEntry(level: .warning, message: pressError))
        }
        return false
    }

    private func setFocus(on element: Element) {
        let elementDescription = element.briefDescription(option: ValueFormatOption.smart)
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "HandleSetFocusedValue: Attempting to set kAXFocusedAttribute to true for \(elementDescription)"))
        if element.setValue(true, forAttribute: AXAttributeNames.kAXFocusedAttribute) {
            return
        }
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .warning,
            message: [
                "HandleSetFocusedValue: Failed to set kAXFocusedAttribute for \(elementDescription),",
                "but proceeding to set value.",
            ].joined(separator: " ")))
    }
}

// TextExtraction.swift - Utilities for extracting text from accessibility elements

import ApplicationServices
import Foundation

@MainActor
public func extractTextFromElement(_ element: Element, maxDepth: Int = 5, currentDepth: Int = 0) -> String? {
    if currentDepth > maxDepth {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "extractTextFromElement: Max depth reached for element: " +
                "\(element.briefDescription(option: ValueFormatOption.smart))"))
        return nil
    }

    // Attempt to get text from common attributes
    if let title = element.title(), !title.isEmpty {
        return title
    }
    if let value = element.value() as? String, !value.isEmpty {
        return value
    }
    if let description = element.descriptionText(), !description.isEmpty {
        return description
    }
    if let help = element.help(), !help.isEmpty {
        return help
    }

    // If no direct text, try children
    var childrenText: [String] = []
    if let children = element.children() { // children() is now synchronous
        for child in children {
            // Removed await
            if let childText = extractTextFromElement(child, maxDepth: maxDepth, currentDepth: currentDepth + 1) {
                childrenText.append(childText)
            }
        }
    }

    if !childrenText.isEmpty {
        return childrenText.joined(separator: " ")
    }

    GlobalAXLogger.shared.log(AXLogEntry(
        level: .debug,
        message: "extractTextFromElement: No text found for element: " +
            "\(element.briefDescription(option: ValueFormatOption.smart))"))
    return nil
}

@MainActor
public func extractTextFromElementNonRecursive(_ element: Element) -> String? {
    // Try attributes that often hold primary text
    if let title = element.title(), !title.isEmpty {
        return title
    }
    if let value = element.value() as? String, !value.isEmpty {
        return value
    }
    if let description = element.descriptionText(), !description.isEmpty {
        return description
    }

    // Fallback to a broader set if primary ones fail
    if let placeholder = element.placeholderValue(), !placeholder.isEmpty {
        return placeholder
    }
    if let help = element.help(), !help.isEmpty {
        return help
    }

    // Consider role description as a last resort if it's textual and meaningful
    // This might be too generic in many cases, so it's lower priority.
    // let roleDesc = element.roleDescription()
    // if let roleDesc = roleDesc, !roleDesc.isEmpty { return roleDesc }

    GlobalAXLogger.shared.log(AXLogEntry(
        level: .debug,
        message: "extractTextFromElementNonRecursive: No direct text found for element: " +
            "\(element.briefDescription(option: ValueFormatOption.smart))"))
    return nil
}

/// More focused text extraction, typically used by handlers.
@MainActor
func getElementTextualContent(
    element: Element,
    includeChildren: Bool = false,
    maxDepth: Int = 1,
    currentDepth: Int = 0) -> String?
{
    let directText = joinedText(from: collectDirectText(from: element))
    let childText = childText(
        for: element,
        includeChildren: includeChildren,
        maxDepth: maxDepth,
        currentDepth: currentDepth)

    let resolved = mergeText(directText: directText, childText: childText)
    logExtractionResult(
        resolvedText: resolved,
        element: element,
        includeChildren: includeChildren,
        depth: currentDepth)
    return resolved
}

@MainActor
private func collectDirectText(from element: Element) -> [String] {
    var pieces: [String] = []
    if let title: String = element.attribute(Attribute<String>.title), !title.isEmpty {
        pieces.append(title)
    }
    if let value: String = element.attribute(Attribute<String>(AXAttributeNames.kAXValueAttribute)), !value.isEmpty {
        pieces.append(value)
    }
    if let description: String = element.attribute(Attribute<String>.description), !description.isEmpty {
        pieces.append(description)
    }
    if let placeholder: String = element.attribute(Attribute<String>.placeholderValue), !placeholder.isEmpty {
        pieces.append(placeholder)
    }
    return pieces
}

@MainActor
private func childText(
    for element: Element,
    includeChildren: Bool,
    maxDepth: Int,
    currentDepth: Int) -> String?
{
    guard includeChildren, currentDepth < maxDepth, let children = element.children() else { return nil }
    let childTexts = children.compactMap { child in
        getElementTextualContent(
            element: child,
            includeChildren: true,
            maxDepth: maxDepth,
            currentDepth: currentDepth + 1)
    }
    return joinedText(from: childTexts)
}

@MainActor
private func joinedText(from pieces: [String]) -> String? {
    let joined = pieces.joined(separator: " ").trimmingCharacters(in: .whitespacesAndNewlines)
    return joined.isEmpty ? nil : joined
}

@MainActor
private func mergeText(directText: String?, childText: String?) -> String? {
    switch (directText, childText) {
    case let (direct?, child?):
        if direct.isEmpty {
            return child
        }
        if child.isEmpty {
            return direct
        }
        return "\(direct) \(child)"
    case let (direct?, nil):
        return direct
    case let (nil, child?):
        return child
    default:
        return nil
    }
}

@MainActor
private func logExtractionResult(
    resolvedText: String?,
    element: Element,
    includeChildren: Bool,
    depth: Int)
{
    let descriptor = element.briefDescription(option: ValueFormatOption.smart)
    if let resolvedText {
        let message = """
        TextExtraction/Content: Extracted '\(resolvedText)' for element
        \(descriptor) (children included: \(includeChildren), depth: \(depth))
        """
        GlobalAXLogger.shared.log(AXLogEntry(level: .debug, message: message))
    } else {
        let message = """
        TextExtraction/Content: No direct text found for \(descriptor)
        (children included: \(includeChildren), depth: \(depth))
        """
        GlobalAXLogger.shared.log(AXLogEntry(level: .debug, message: message))
    }
}

// AccessibilityPermissions.swift - Utility for checking and managing accessibility permissions.

import ApplicationServices // For AXIsProcessTrusted(), AXUIElementCreateSystemWide(), etc.

// Removed private let kAXTrustedCheckOptionPromptKey = "AXTrustedCheckOptionPrompt"

// debug() is assumed to be globally available from Logging.swift
// getParentProcessName() is assumed to be globally available from ProcessUtils.swift
// kAXFocusedUIElementAttribute is assumed to be globally available from AccessibilityConstants.swift
// AccessibilityError is from AccessibilityError.swift

public struct AXPermissionsStatus {
    public let isAccessibilityApiEnabled: Bool
    public let isProcessTrustedForAccessibility: Bool

    @available(
        *,
        deprecated,
        message: "AXorcist no longer probes Apple Events automation permission; this status remains empty.")
    public var automationStatus: [String: Bool] = [:]
    public var overallErrorMessages: [String] = []

    public var canUseAccessibility: Bool {
        self.isAccessibilityApiEnabled && self.isProcessTrustedForAccessibility
    }

    @available(
        *,
        deprecated,
        message: "AXorcist no longer probes Apple Events automation permission; this result is unknown.")
    public func canAutomate(bundleID: String) -> Bool? {
        self.automationStatus[bundleID]
    }
}

@MainActor
public func checkAccessibilityPermissions(promptIfNeeded: Bool = true) throws {
    let hasPermissions = promptIfNeeded ?
        AXPermissionHelpers.askForAccessibilityIfNeeded() :
        AXPermissionHelpers.hasAccessibilityPermissions()

    if !hasPermissions {
        let parentName = getParentProcessName()
        let errorDetail = parentName != nil ? "Hint: Grant accessibility permissions to \(parentName!)." :
            "Hint: Ensure the application running this tool has Accessibility permissions."
        axErrorLog(
            "Accessibility check failed. Details: \(errorDetail)",
            file: #file,
            function: #function,
            line: #line)
        throw AccessibilityError.notAuthorized(errorDetail)
    } else {
        axDebugLog(
            "Accessibility permissions are granted.",
            file: #file,
            function: #function,
            line: #line)
    }
}

@MainActor
public func getPermissionsStatus() -> AXPermissionsStatus {
    axDebugLog(
        "Starting Accessibility permission status check.",
        file: #file,
        function: #function,
        line: #line)

    let isProcessTrusted = AXPermissionHelpers.hasAccessibilityPermissions()
    let isSandboxed = AXPermissionHelpers.isSandboxed()

    if isSandboxed {
        axWarningLog("Process is running in sandbox, some features may be limited.")
    }

    logProcessTrustStatus(isProcessTrusted)

    let finalStatus = AXPermissionsStatus(
        isAccessibilityApiEnabled: isProcessTrusted,
        isProcessTrustedForAccessibility: isProcessTrusted,
        automationStatus: [:],
        overallErrorMessages: [])
    axDebugLog(
        "Finished permission status check. isAccessibilityApiEnabled: \(finalStatus.isAccessibilityApiEnabled), " +
            "isProcessTrusted: \(finalStatus.isProcessTrustedForAccessibility)",
        file: #file,
        function: #function,
        line: #line)
    return finalStatus
}

/// Returns Accessibility permission status without probing Apple Events automation permission.
///
/// The bundle identifiers are ignored and ``AXPermissionsStatus/automationStatus`` remains empty.
/// This overload is retained only so existing source continues to compile while callers migrate to
/// ``getPermissionsStatus()``.
@available(
    *,
    deprecated,
    message: "Apple Events automation permission probing was removed; call getPermissionsStatus() instead.")
@MainActor
public func getPermissionsStatus(checkAutomationFor _: [String]) -> AXPermissionsStatus {
    getPermissionsStatus()
}

private func logProcessTrustStatus(_ isProcessTrusted: Bool) {
    axDebugLog(
        "AXIsProcessTrusted() returned: \(isProcessTrusted)",
        file: #file,
        function: #function,
        line: #line)
    if !isProcessTrusted {
        let parentName = getParentProcessName()
        let hint = parentName != nil ? "Hint: Grant accessibility permissions to \(parentName!)." :
            "Hint: Ensure the application running this tool has Accessibility permissions."
        axWarningLog(
            "Process is not trusted for Accessibility. \(hint)",
            file: #file,
            function: #function,
            line: #line)
    }
}

//
//  AXPermissionHelpers.swift
//  AXorcist
//
//  Enhanced accessibility permissions utilities
//

import ApplicationServices
import Foundation

/// Utilities for managing macOS accessibility permissions.
///
/// This structure provides convenient methods for checking and requesting accessibility
/// permissions required for AXorcist to function properly. It also includes modern
/// async/await APIs for permission monitoring.
///
/// ## Topics
///
/// ### Permission Checking
/// - ``hasAccessibilityPermissions()``
/// - ``askForAccessibilityIfNeeded()``
/// - ``isSandboxed()``
///
/// ### Async Permission Management
/// - ``requestPermissions()``
/// - ``permissionChanges(interval:)``
public enum AXPermissionHelpers {
    /// Requests accessibility permissions if needed, showing the system prompt.
    ///
    /// This method will display the macOS system dialog asking the user to grant
    /// accessibility permissions if they haven't been granted already.
    ///
    /// - Returns: `true` if permissions are granted (either already or after user approval),
    ///           `false` if permissions are denied or the dialog is dismissed
    ///
    /// ## Important
    /// Only call this method when you're ready to present the system permission dialog
    /// to the user. Consider using ``hasAccessibilityPermissions()`` first to check
    /// current permission status.
    @MainActor
    public static func askForAccessibilityIfNeeded() -> Bool {
        // Skip permission dialog in test environment
        if ProcessInfo.processInfo.environment["XCTestConfigurationFilePath"] != nil ||
            ProcessInfo.processInfo.arguments.contains("--test-mode") ||
            NSClassFromString("XCTest") != nil
        {
            return false // Return false to indicate no permissions in test mode
        }
        let options = [CFConstants.axTrustedCheckOptionPrompt as String: true]
        return AXIsProcessTrustedWithOptions(options as CFDictionary?)
    }

    /// Checks if the app currently has accessibility permissions without prompting.
    ///
    /// Use this method to check permission status without triggering the system
    /// permission dialog.
    ///
    /// - Returns: `true` if accessibility permissions are granted, `false` otherwise
    @MainActor
    public static func hasAccessibilityPermissions() -> Bool {
        AXIsProcessTrusted()
    }

    /// Determines if the app is running in a sandboxed environment.
    ///
    /// This can be useful for adjusting behavior based on the app's security context,
    /// as sandboxed apps may have different accessibility permission requirements.
    ///
    /// - Returns: `true` if the app is sandboxed, `false` otherwise
    public static func isSandboxed() -> Bool {
        let environment = ProcessInfo.processInfo.environment
        return environment["APP_SANDBOX_CONTAINER_ID"] != nil
    }

    // MARK: - Modern Async/Await API

    /// Requests accessibility permissions asynchronously.
    ///
    /// This async version of permission requesting provides a more modern API
    /// for Swift concurrency environments. It will show the system permission
    /// prompt if permissions haven't been granted.
    ///
    /// - Returns: `true` if permissions are granted, `false` otherwise
    ///
    /// ## Example
    ///
    /// ```swift
    /// let hasPermissions = await AXPermissionHelpers.requestPermissions()
    /// if hasPermissions {
    ///     // Proceed with accessibility operations
    /// } else {
    ///     // Handle permission denial
    /// }
    /// ```
    ///
    /// > Important: This method will display the system permission dialog.
    /// > Only call it when appropriate for your user experience.
    public static func requestPermissions() async -> Bool {
        await MainActor.run {
            self.askForAccessibilityIfNeeded()
        }
    }

    /// Monitors accessibility permission changes as an AsyncStream.
    ///
    /// This method provides a reactive way to observe permission state changes
    /// over time, useful for updating UI or taking actions when permissions
    /// are granted or revoked.
    ///
    /// - Parameter interval: The polling interval in seconds (default: 1.0)
    /// - Returns: An ``AsyncStream<Bool>`` that emits permission status changes
    ///
    /// ## Example
    ///
    /// ```swift
    /// for await hasPermissions in AXPermissionHelpers.permissionChanges() {
    ///     if hasPermissions {
    ///         print("Permissions granted!")
    ///         // Enable accessibility features
    ///     } else {
    ///         print("Permissions revoked!")
    ///         // Disable accessibility features
    ///     }
    /// }
    /// ```
    ///
    /// > Note: The stream automatically cleans up its timer when cancelled.
    public static func permissionChanges(
        interval: TimeInterval = 1.0) -> AsyncStream<Bool>
    {
        self.permissionChanges(
            interval: interval,
            beforeTimerInstall: nil,
            onTimerScheduled: nil)
    }

    nonisolated static func permissionChanges(
        interval: TimeInterval,
        beforeTimerInstall: (@MainActor () -> Void)? = nil,
        onTimerScheduled: (@MainActor () -> Void)?) -> AsyncStream<Bool>
    {
        AsyncStream { continuation in
            let timerBox = PermissionChangeTimerBox()

            let start: @MainActor () -> Void = {
                guard !timerBox.isTerminated else { return }
                let initialState = self.hasAccessibilityPermissions()
                timerBox.lastState = initialState
                continuation.yield(initialState)
                let timer = Timer(timeInterval: interval, repeats: true) { _ in
                    let currentState = MainActor.assumeIsolated {
                        self.hasAccessibilityPermissions()
                    }
                    if currentState != timerBox.lastState {
                        timerBox.lastState = currentState
                        continuation.yield(currentState)
                    }
                }
                beforeTimerInstall?()
                guard timerBox.installTimerIfActive(timer) else {
                    timer.invalidate()
                    return
                }
                onTimerScheduled?()
            }
            Self.hopToMainActor(start)

            continuation.onTermination = { @Sendable _ in
                timerBox.markTerminated()
                Self.hopToMainActor {
                    timerBox.invalidateTimer()
                }
            }
        }
    }

    @inline(__always)
    private nonisolated static func hopToMainActor(_ work: @escaping @MainActor () -> Void) {
        if Thread.isMainThread {
            MainActor.assumeIsolated(work)
            return
        }
        DispatchQueue.main.async {
            MainActor.assumeIsolated(work)
        }
    }
}

private final nonisolated class PermissionChangeTimerBox: @unchecked Sendable {
    private let lock = NSLock()
    var timer: Timer?
    var lastState: Bool?
    private var terminatedFlag = false

    var isTerminated: Bool {
        self.lock.lock()
        defer { self.lock.unlock() }
        return self.terminatedFlag
    }

    func markTerminated() {
        self.lock.lock()
        self.terminatedFlag = true
        self.lock.unlock()
    }

    @MainActor
    func installTimerIfActive(_ timer: Timer) -> Bool {
        self.lock.lock()
        defer { self.lock.unlock() }
        guard !self.terminatedFlag else { return false }

        self.timer = timer
        RunLoop.main.add(timer, forMode: .default)
        return true
    }

    @MainActor
    func invalidateTimer() {
        self.lock.lock()
        let timer = self.timer
        self.timer = nil
        self.lock.unlock()
        timer?.invalidate()
    }
}

// NavigationUtils.swift - Additional navigation utilities

import Foundation

/// This function demonstrates the requested pattern for trimming whitespace before splitting
@MainActor
public func navigateToElementWithTrimming(
    pathComponents: [String]) -> [(String, String)]
{
    var results: [(String, String)] = []

    for pathComponentString in pathComponents {
        // Add the requested trimming line before the split operation
        let trimmedPathComponentString = pathComponentString.trimmingCharacters(in: .whitespacesAndNewlines)

        // Use the trimmed string in the split call
        let parts = trimmedPathComponentString.split(separator: ":", maxSplits: 1)

        if parts.count == 2 {
            results.append((String(parts[0]), String(parts[1])))
        }
    }

    return results
}

// GeometryHelpers.swift - Helper functions for geometry type conversions

import CoreGraphics
import Foundation

/// Helper functions to convert CoreGraphics types to dictionaries for JSON serialization
/// These are needed because AnyCodable might not handle them directly as dictionaries.
func NSPointToDictionary(_ point: CGPoint) -> [String: CGFloat] {
    ["x": point.x, "y": point.y]
}

func NSSizeToDictionary(_ size: CGSize) -> [String: CGFloat] {
    ["width": size.width, "height": size.height]
}

// PathHintComponent.swift - Path hint component for basic string path hints

import Foundation

// MARK: - PathHintComponent Definition

/// This PathHintComponent is simpler and used for basic string path hints if ever needed again.
/// For new functionality, JSONPathHintComponent is preferred.
@MainActor
public struct PathHintComponent {
    // MARK: Lifecycle

    public init?(pathSegment: String) {
        self.originalSegment = pathSegment
        var parsedCriteria = PathUtils.parseRichPathComponent(pathSegment)

        if parsedCriteria.isEmpty {
            let fallbackPairs = pathSegment
                .split(separator: ",")
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            for pair in fallbackPairs {
                let keyValue = pair.split(separator: "=", maxSplits: 1)
                    .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                if keyValue.count == 2 {
                    parsedCriteria[String(keyValue[0])] = String(keyValue[1])
                }
            }
        }

        var mappedCriteria: [String: String] = [:]
        for (rawKey, value) in parsedCriteria {
            if let mappedKey = Self.attributeAliases[rawKey] {
                mappedCriteria[mappedKey] = value
            } else {
                mappedCriteria[rawKey] = value // Keep unmapped keys as-is
            }
        }

        if mappedCriteria.isEmpty {
            axWarningLog("PathHintComponent: Path segment '\(pathSegment)' produced no usable criteria after parsing.")
            return nil
        }
        self.criteria = mappedCriteria
        axDebugLog("PathHintComponent initialized. Segment: '\(pathSegment)' => criteria: \(mappedCriteria)")
    }

    init(criteria: [String: String], originalSegment: String = "") {
        self.criteria = criteria
        self.originalSegment = originalSegment.isEmpty && !criteria.isEmpty ? "criteria_only_init" : originalSegment
    }

    // MARK: Public

    public let criteria: [String: String]
    public let originalSegment: String

    // MARK: Internal

    /// PathHintComponent uses exact matching by default when calling elementMatchesCriteria
    func matches(element: Element) -> Bool {
        elementMatchesCriteria(
            element,
            criteria: self.criteria,
            matchType: JSONPathHintComponent.MatchType.exact)
    }

    // MARK: Private

    // Corrected: PathUtils.attributeKeyMappings might be the intended property
    // Ensure this is the correct static property in PathUtils
    private static let attributeAliases: [String: String] = PathUtils.attributeKeyMappings
}

// AttributeExtractors.swift - Low-level attribute extraction logic

import ApplicationServices
import Foundation

// MARK: - Internal Fetch Logic Helpers

@MainActor
func determineAttributesToFetch(
    requestedAttributes: [String]?,
    forMultiDefault: Bool,
    targetRole: String?,
    element: Element) -> [String]
{
    if forMultiDefault {
        return defaultMultiAttributes(for: targetRole)
    }

    if let requested = requestedAttributes, !requested.isEmpty {
        return requested
    }

    return fetchAllAttributeNames(from: element)
}

@MainActor
private func fetchAllAttributeNames(from element: Element) -> [String] {
    guard let names = element.attributeNames(), !names.isEmpty else {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message: "determineAttributesToFetch: Falling back to defaults; unable to fetch attribute names."))
        return []
    }

    GlobalAXLogger.shared.log(AXLogEntry(
        level: .debug,
        message: "determineAttributesToFetch: No specific attributes requested, fetched all \(names.count)"))
    return names
}

private func defaultMultiAttributes(for role: String?) -> [String] {
    AttributeDefaultSet(role: role).attributes
}

private struct AttributeDefaultSet {
    let role: String?

    var attributes: [String] {
        let base = [
            AXAttributeNames.kAXRoleAttribute,
            AXAttributeNames.kAXValueAttribute,
            AXAttributeNames.kAXTitleAttribute,
            AXAttributeNames.kAXIdentifierAttribute,
        ]
        guard self.role == AXRoleNames.kAXStaticTextRole else { return base }
        return [
            AXAttributeNames.kAXRoleAttribute,
            AXAttributeNames.kAXValueAttribute,
            AXAttributeNames.kAXIdentifierAttribute,
        ]
    }
}

/// Function to get specifically computed attributes for an element
@MainActor
func getComputedAttributes(for element: Element) async -> [String: AttributeData] {
    var computedAttrs: [String: AttributeData] = [:]

    if let name = element.computedName() {
        computedAttrs[AXMiscConstants.computedNameAttributeKey] = AttributeData(
            value: .string(name),
            source: .computed)
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message:
            "getComputedAttributes: Computed name for element " +
                "\(element.briefDescription(option: .raw)) is '\(name)'."))
    } else {
        GlobalAXLogger.shared.log(AXLogEntry(
            level: .debug,
            message:
            "getComputedAttributes: Element \(element.briefDescription(option: .raw)) " +
                "has no computed name."))
    }

    return computedAttrs
}

// AttributeFormatter.swift - Contains functions for formatting element attributes for display

import ApplicationServices
import Foundation

/// Helper function to format the parent attribute
@MainActor
func formatParentAttribute(
    _ parent: Element?,
    outputFormat: OutputFormat,
    valueFormatOption: ValueFormatOption) -> AttributeValue
{
    guard let parentElement = parent else { return .null }
    if outputFormat == .textContent {
        return .string("Element: \(parentElement.role() ?? "?Role")")
    } else {
        return .string(parentElement.briefDescription(option: valueFormatOption))
    }
}

/// Helper function to format the children attribute
@MainActor
func formatChildrenAttribute(
    _ children: [Element]?,
    outputFormat: OutputFormat,
    valueFormatOption: ValueFormatOption) -> AttributeValue
{
    guard let actualChildren = children, !actualChildren.isEmpty else {
        return .null
    }

    let descriptions = actualChildren.map { $0.briefDescription(option: valueFormatOption) }
    return outputFormat == .textContent
        ? .string("[\(descriptions.joined(separator: ", "))]")
        : .array(descriptions.map { .string($0) })
}

/// Helper function to format the focused UI element attribute
@MainActor
func formatFocusedUIElementAttribute(
    _ focusedElement: Element?,
    outputFormat: OutputFormat,
    valueFormatOption: ValueFormatOption) -> AttributeValue
{
    guard let actualFocusedElement = focusedElement else { return .null }
    if outputFormat == .textContent {
        return .string(
            "Focused: \(actualFocusedElement.role() ?? "?Role") - \(actualFocusedElement.title() ?? "?Title")")
    } else {
        return .string(actualFocusedElement.briefDescription(option: valueFormatOption))
    }
}

